import React, { useState } from 'react';

const MemberManagementTab = () => {
    // 가상의 회원 목록 (실제로는 백엔드에서 가져올 데이터)
    const [members, setMembers] = useState([
        { id: 1, memberNo: 1001, nickname: '도몬', email: 'domon@example.com', status: '정상', registeredDate: '2024-01-01' }, // memberNo 추가
        { id: 2, memberNo: 1002, nickname: '여행가Lv1', email: 'traveler1@example.com', status: '정지', registeredDate: '2024-02-10' }, // memberNo 추가
        { id: 3, memberNo: 1003, nickname: '사찰지킴이', email: 'templefan@example.com', status: '정상', registeredDate: '2024-03-20' }, // memberNo 추가
        { id: 4, memberNo: 1004, nickname: '탈퇴예정', email: 'withdrawal@example.com', status: '탈퇴', registeredDate: '2024-04-05' }, // memberNo 추가
    ]);

    // 검색 상태를 관리할 state 추가
    const [searchTerm, setSearchTerm] = useState('');
    const [searchType, setSearchType] = useState('nickname'); // 기본 검색 기준: 닉네임

    const handleMemberAction = (memberId, actionType) => {
        // 실제 백엔드 API 호출 로직 (여기서는 가상 처리)
        const member = members.find(m => m.id === memberId);
        if (!member) return;

        if (actionType === '정지') {
            alert(`${member.nickname} 님을 정지 처리합니다. (API 연동 필요)`);
            setMembers(members.map(m => m.id === memberId ? { ...m, status: '정지' } : m));
        } else if (actionType === '활성') { // 정지된 회원을 다시 정상으로 돌릴 때 사용
            alert(`${member.nickname} 님을 정상 처리합니다. (API 연동 필요)`);
            setMembers(members.map(m => m.id === memberId ? { ...m, status: '정상' } : m));
        }
        else if (actionType === '탈퇴') {
            if (window.confirm(`${member.nickname} 님을 정말 탈퇴 처리하시겠습니까?`)) {
                alert(`${member.nickname} 님을 탈퇴 처리합니다. (API 연동 필요)`);
                setMembers(members.map(m => m.id === memberId ? { ...m, status: '탈퇴' } : m));
            }
        }
    };

    // 검색 로직
    const filteredMembers = members.filter(member => {
        if (searchTerm === '') {
            return true; // 검색어가 없으면 모두 표시
        }
        const lowerCaseSearchTerm = searchTerm.toLowerCase();
        if (searchType === 'id') {
            return String(member.id).includes(lowerCaseSearchTerm);
        } else if (searchType === 'memberNo') { // 회원 번호 검색 추가
            return String(member.memberNo).includes(lowerCaseSearchTerm);
        } else if (searchType === 'nickname') {
            return member.nickname.toLowerCase().includes(lowerCaseSearchTerm);
        } else if (searchType === 'email') {
            return member.email.toLowerCase().includes(lowerCaseSearchTerm);
        }
        return false;
    });

    return (
        <div className="tab-content-section member-management-tab">
            <h3 className="tab-content-title">회원 관리 🧑‍🤝‍🧑</h3>
            <div className="search-form">
                <select
                    className="search-select" // 새로운 클래스 추가
                    value={searchType}
                    onChange={(e) => setSearchType(e.target.value)}
                >
                    <option value="memberNo">회원 번호</option> {/* 회원 번호 검색 기준 추가 */}
                    <option value="id">ID</option>
                    <option value="nickname">닉네임</option>
                    <option value="email">이메일</option>
                </select>
                <input
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
                <button className="search-button">검색</button>
            </div>

            <table className="admin-member-table">
                <thead>
                    <tr>
                        <th>회원 번호</th> {/* 'ID' 대신 '회원 번호'로 변경 */}
                        <th>ID</th> {/* 기존 ID 열 추가 */}
                        <th>닉네임</th>
                        <th>이메일</th>
                        <th>가입일</th>
                        <th>상태</th>
                        <th>액션</th>
                    </tr>
                </thead>
                <tbody>
                    {filteredMembers.map(member => (
                        <tr key={member.id}>
                            <td>{member.memberNo}</td> {/* 회원 번호 표시 */}
                            <td>{member.id}</td> {/* ID 표시 */}
                            <td>{member.nickname}</td>
                            <td>{member.email}</td>
                            <td>{member.registeredDate}</td>
                            <td>
                                <span className={
                                    member.status === '정상' ? 'member-status-active' : 'member-status-inactive'
                                }>
                                    {member.status}
                                </span>
                            </td>
                            <td className="member-actions">
                                {member.status === '정상' && ( // 정지 또는 탈퇴 상태가 아닐 때만 정지 버튼
                                    <button className="action-button delete-button" onClick={() => handleMemberAction(member.id, '정지')}>정지</button>
                                )}
                                {member.status === '정지' && ( // 정지 상태일 때만 활성 버튼
                                    <button className="action-button" onClick={() => handleMemberAction(member.id, '활성')}>활성</button>
                                )}
                                {member.status !== '탈퇴' && ( // 탈퇴 상태가 아닐 때만 탈퇴 버튼
                                    <button className="action-button delete-button" onClick={() => handleMemberAction(member.id, '탈퇴')}>탈퇴</button>
                                )}
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};

export default MemberManagementTab;
